/* ═══════ AUDIO ═══════ */
let _a;const ac=()=>{if(!_a)_a=new(window.AudioContext||window.webkitAudioContext)();if(_a.state==="suspended")_a.resume();return _a;};
const bp=(f,d,w="sine",v=.18)=>{try{const c=ac(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.type=w;o.frequency.value=f;g.gain.setValueAtTime(v,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+d);o.start();o.stop(c.currentTime+d);}catch(_){}};
const sfx={tap:()=>bp(880,.06),tick:()=>bp(660,.1,"square",.12),go:()=>{bp(880,.12,"square",.2);setTimeout(()=>bp(1100,.16,"square",.16),70);},good:()=>{bp(523,.1);setTimeout(()=>bp(659,.1),80);setTimeout(()=>bp(784,.16),160);},great:()=>{[523,659,784,1047].forEach((f,i)=>setTimeout(()=>bp(f,.12),i*65));},bad:()=>{bp(380,.12,"sawtooth",.08);setTimeout(()=>bp(280,.2,"sawtooth",.06),100);},win:()=>{[523,659,784,1047,784,1047].forEach((f,i)=>setTimeout(()=>bp(f,.14),i*100));},elim:()=>{bp(200,.3,"sawtooth",.14);setTimeout(()=>bp(150,.4,"sawtooth",.09),160);},reveal:()=>{bp(330,.25,"triangle",.15);setTimeout(()=>bp(550,.3,"triangle",.12),250);},drama:()=>{[200,250,300,350,400,500,600,800].forEach((f,i)=>setTimeout(()=>bp(f,.1,"triangle",.08+i*.02),i*100));}};
const vb=p=>{try{navigator.vibrate?.(p);}catch(_){}};
const H={l:()=>vb(10),m:()=>vb(25),h:()=>vb([50,25,50]),ok:()=>vb([25,40,25,40,70])};

/* ═══════ CSS ═══════ */
const CSS=`*{box-sizing:border-box}
@keyframes pop{0%{transform:scale(.3);opacity:0}60%{transform:scale(1.06)}100%{transform:scale(1);opacity:1}}
@keyframes up{from{transform:translateY(20px);opacity:0}to{transform:translateY(0);opacity:1}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes cPop{0%{transform:scale(.5);opacity:0}50%{transform:scale(1.15)}100%{transform:scale(1);opacity:1}}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
@keyframes breathe{0%,100%{transform:scale(1);opacity:.35}50%{transform:scale(1.12);opacity:.75}}
@keyframes ripple{0%{transform:scale(.8);opacity:.5}100%{transform:scale(2);opacity:0}}
@keyframes flash{0%{opacity:0;transform:scale(.5)}40%{opacity:1;transform:scale(1.1)}100%{transform:scale(1)}}
@keyframes conf{0%{transform:translateY(0) rotate(0);opacity:1}100%{transform:translateY(220px) rotate(720deg);opacity:0}}
@keyframes sL{from{transform:translateX(-14px);opacity:0}to{transform:translateX(0);opacity:1}}
@keyframes pulse{0%,100%{opacity:.5}50%{opacity:1}}
@keyframes dotP{0%,80%,100%{opacity:.3}40%{opacity:1}}
@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-6px)}75%{transform:translateX(6px)}}
@keyframes glow{0%,100%{filter:brightness(1)}50%{filter:brightness(1.3)}}`;

/* ═══════ HELPERS ═══════ */
function genTgt(r,d="medium",tm=false,iz=false){if(tm)return Math.round((15+Math.random()*10)*10)/10;if(iz){let lo,hi;if(r<=2){lo=3;hi=6;}else if(r<=5){lo=4;hi=8;}else{lo=5;hi=12;}return Math.round((lo+Math.random()*(hi-lo))*10)/10;}let lo,hi;if(r<=2){lo=1;hi=3;}else if(r<=5){lo=2;hi=6;}else{lo=3;hi=10;}let t=lo+Math.random()*(hi-lo);if(d==="easy")t=Math.round(t);else if(d==="medium")t=Math.round(t*10)/10;else t=Math.round(t*100)/100;return Math.max(lo,t);}
function fmt(t,d){return t.toFixed(d==="easy"?0:d==="medium"?1:2);}
function scoreMs(a,t){return Math.round(Math.abs(a-t)*1000);}
function grade(ms){if(ms<=30)return{k:"perf",c:A.am,i:"\u2B50"};if(ms<=100)return{k:"strong",c:A.em,i:"\uD83D\uDD25"};if(ms<=250)return{k:"good",c:A.v,i:"\uD83D\uDC4D"};if(ms<=500)return{k:"close",c:"#A5A3C8",i:"\uD83E\uDD14"};return{k:"miss",c:A.ro,i:"\uD83D\uDCA8"};}
function pts(ms,d){const tl=d==="easy"?500:d==="medium"?250:100;return Math.round(Math.max(0,1-ms/tl)*1000);}
const medal=r=>r===1?"\uD83E\uDD47":r===2?"\uD83E\uDD48":r===3?"\uD83E\uDD49":`#${r}`;

/* ═══════ ATOMS ═══════ */
function Btn({children,onClick,style,primary,small,disabled,gradient}){const{T}=useApp();const[p,sP]=useState(false);return <button onClick={()=>{if(disabled)return;sfx.tap();H.l();sP(true);setTimeout(()=>sP(false),150);onClick?.();}} style={{background:gradient||(primary?GR.brand:T.raised),border:primary||gradient?"none":`1px solid ${T.ln}`,borderRadius:small?10:14,padding:small?"10px 18px":"16px 36px",color:"#fff",fontSize:small?13:15,fontWeight:primary||gradient?800:600,letterSpacing:primary||gradient?1.5:0,cursor:disabled?"default":"pointer",textTransform:primary||gradient?"uppercase":"none",fontFamily:"inherit",transform:p?"scale(.94)":"scale(1)",transition:"transform .12s",opacity:disabled?.3:1,boxShadow:primary||gradient?GL(A.v,10):"none",...style}}>{children}</button>;}

function Buzzer({state,onTap,size=175,label}){const[p,sP]=useState(false);useEffect(()=>{if(state==="timing"){const i=setInterval(()=>sP(v=>!v),450);return()=>clearInterval(i);}sP(false);},[state]);const cfg={ready:{bg:GR.brand,lb:label||"START",sh:A.v},timing:{bg:GR.warm,lb:"STOP",sh:A.ro},done:{bg:`linear-gradient(135deg,#5D5B7A,#555)`,lb:"\u2713",sh:"#5D5B7A"}}[state]||{bg:GR.brand,lb:"",sh:A.v};const ok=state==="ready"||state==="timing";return <div style={{position:"relative",width:size,height:size,margin:"0 auto"}}><div style={{position:"absolute",inset:-10,borderRadius:"50%",background:cfg.sh,opacity:p?.2:.06,transition:"opacity .4s",filter:"blur(16px)"}}/><button onClick={ok?()=>{sfx.tap();H.m();onTap?.();}:undefined} style={{width:size,height:size,borderRadius:"50%",background:cfg.bg,border:"3px solid rgba(255,255,255,.2)",cursor:ok?"pointer":"default",display:"flex",alignItems:"center",justifyContent:"center",transform:p&&state==="timing"?"scale(1.03)":"scale(1)",transition:"transform .3s",boxShadow:GL(cfg.sh,24),position:"relative",zIndex:1,fontFamily:"inherit"}}><span style={{color:"#fff",fontSize:16,fontWeight:900,letterSpacing:4}}>{cfg.lb}</span></button></div>;}

function Confetti(){const cc=[A.v,A.pk,A.am,A.em,A.cy,A.or];return <div style={{position:"fixed",inset:0,pointerEvents:"none",overflow:"hidden",zIndex:999}}>{Array.from({length:30},(_,i)=><div key={i} style={{position:"absolute",top:-12,left:`${Math.random()*100}%`,width:5+Math.random()*8,height:5+Math.random()*8,borderRadius:i%3===0?"50%":2,background:cc[i%cc.length],animation:`conf ${1.2+Math.random()*1.3}s ease ${Math.random()*1.3}s forwards`}}/>)}</div>;}

function Countdown3({onDone}){const{t}=useApp();const[v,sV]=useState(3);useEffect(()=>{sfx.tick();H.l();const a=setTimeout(()=>{sV(2);sfx.tick();H.l();},1e3),b=setTimeout(()=>{sV(1);sfx.tick();H.m();},2e3),c=setTimeout(()=>{sV(0);sfx.go();H.h();},3e3),d=setTimeout(onDone,3500);return()=>{clearTimeout(a);clearTimeout(b);clearTimeout(c);clearTimeout(d);};},[]);return <div style={{textAlign:"center",padding:"50px 0"}}><div style={{fontSize:10,color:"#5D5B7A",letterSpacing:3,textTransform:"uppercase",marginBottom:8}}>{t("getReady")}</div><div key={v} style={{fontSize:96,fontWeight:900,background:v===0?GR.warm:GR.cool,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",animation:"cPop .3s ease"}}>{v===0?"GO!":v}</div></div>;}

/* ═══════ SETTINGS PICKER ═══════ */
function SPick({onDone,showDiff=true,title,sub2}){const{t,T}=useApp();const[d,sD]=useState(null);
  if(showDiff&&!d)return <div style={{animation:"up .4s ease",textAlign:"center"}}><div style={{fontSize:18,fontWeight:800,color:T.tx,marginBottom:4}}>{title||t("diff")}</div>{sub2&&<div style={{fontSize:12,color:T.sub,marginBottom:16}}>{sub2}</div>}<div style={{display:"flex",flexDirection:"column",gap:10,maxWidth:340,margin:"0 auto"}}>{[{id:"easy",k:"easy",dk:"easyD",gr:GR.mint,cl:A.em,ic:"\u2B50"},{id:"medium",k:"med",dk:"medD",gr:GR.sun,cl:A.am,ic:"\uD83D\uDD25"},{id:"hard",k:"hard",dk:"hardD",gr:GR.warm,cl:A.ro,ic:"\uD83D\uDCA5"}].map((x,i)=><button key={x.id} onClick={()=>{sfx.tap();sD(x.id);}} style={{background:T.card,borderRadius:16,border:`1px solid ${T.ln}`,padding:"16px 18px",display:"flex",alignItems:"center",gap:14,cursor:"pointer",fontFamily:"inherit",textAlign:"left",animation:`sL .3s ease ${i*.05}s both`}}><div style={{width:44,height:44,borderRadius:12,background:x.gr,display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,flexShrink:0,boxShadow:GL(x.cl,8)}}>{x.ic}</div><div><div style={{fontSize:15,fontWeight:800,color:T.tx}}>{t(x.k)}</div><div style={{fontSize:11,color:T.sub}}>{t(x.dk)}</div></div></button>)}</div></div>;
  return <div style={{animation:"up .4s ease",textAlign:"center"}}><div style={{fontSize:18,fontWeight:800,color:T.tx,marginBottom:4}}>{t("rndCnt")}</div><div style={{fontSize:12,color:T.sub,marginBottom:20}}>{t("howMany")}</div><div style={{display:"flex",gap:12,justifyContent:"center"}}>{[1,3,5].map(r=><button key={r} onClick={()=>{sfx.tap();H.l();onDone(showDiff?d:"medium",r);}} style={{width:70,height:70,borderRadius:16,background:GR.brand,border:"none",color:"#fff",fontSize:28,fontWeight:900,cursor:"pointer",fontFamily:"inherit",boxShadow:GL(A.v,12),transition:"transform .15s"}} onMouseEnter={e=>e.currentTarget.style.transform="scale(1.08)"} onMouseLeave={e=>e.currentTarget.style.transform="scale(1)"}>{r}</button>)}</div></div>;
}

